    val keys: Set<String> get() = labels.keys

    fun resolve(text: String?, languageCode: String): String? {
        if (text == null) return null
        val index = languageIndexes[languageCode.lowercase(Locale.ROOT)] ?: 0
        return LABEL_PATTERN.replace(text) { match ->
            labels[match.groupValues[1]]?.getOrNull(index) ?: match.value
        }
    }

    fun localize(screen: Screen, languageCode: String): Screen = screen.copy(
        title = resolve(screen.title, languageCode).orEmpty(),
        subtitle = resolve(screen.subtitle, languageCode),
        blocks = screen.blocks.map { localize(it, languageCode) },
    )

    private fun localize(block: Block, languageCode: String): Block = block.copy(
        text = resolve(block.text, languageCode),
        title = resolve(block.title, languageCode),
        sub = resolve(block.sub, languageCode),
        label = resolve(block.label, languageCode),
        prefix = resolve(block.prefix, languageCode),
        placeholder = resolve(block.placeholder, languageCode),
        hint = resolve(block.hint, languageCode),
        options = block.options?.map { resolve(it, languageCode).orEmpty() },
        name = resolve(block.name, languageCode),
        hello = resolve(block.hello, languageCode),
        forgot = resolve(block.forgot, languageCode),
        tag = resolve(block.tag, languageCode),
        amount = resolve(block.amount, languageCode),
        number = resolve(block.number, languageCode),
        holder = resolve(block.holder, languageCode),
        extra = resolve(block.extra, languageCode),
        badge = resolve(block.badge, languageCode),
        lead = resolve(block.lead, languageCode),
        link = resolve(block.link, languageCode),
        children = block.children?.map { localize(it, languageCode) },
        items = block.items?.map { item ->
            item.copy(
                name = resolve(item.name, languageCode),
                label = resolve(item.label, languageCode),
                amount = resolve(item.amount, languageCode),
            )
        },
        trailing = block.trailing?.copy(text = resolve(block.trailing.text, languageCode)),
    )
}
